#pragma once

// Recompiled SNR2 module (DLL) code compiled into kamite.exe. One ModulePack per (module, load base), written by
// 'python -I build.py modules <mod>' into generated_modules/<mod>/<mod>_pack.cpp from the module's
// register_functions.cpp (every "g_ps2RecompiledFunctionTable[slot] = name; // 0xADDR" line, resume entries included).
// The list of packs (modulePacks) is generated by src/CMakeLists.txt from the generated_modules/*/ folders.
// function_hooks.cpp installs a pack's entries in the runtime's module table (ps2_module_table.h) when the guest
// registers the image (SNR2 0x394C18) and clears them when it unregisters it (0x394D00).

#include "ps2_module_table.h"

#include <cstddef>
#include <cstdint>

namespace kamite
{
    struct ModuleEntry
    {
        uint32_t address;
        ps2x::ModuleFunction function;
    };

    struct ModulePack
    {
        const char *imageName;        // SNR2 header+0x14 string, e.g. "..\\PS2_EE_Release\\McPort.elf"
        uint32_t base;                // image address the code was generated for (physical)
        uint32_t size;                // header+0x2C (file size)
        uint32_t textBegin;           // code range checked by the guard (absolute, physical)
        uint32_t textEnd;
        const char *maskedTextSha256; // sha256 of [textBegin, textEnd) with every liveSites word zeroed
        const uint32_t *liveSites;    // runtime-relocation sites in the module code (imports read live); may be null
        size_t liveSiteCount;
        const ModuleEntry *entries;   // dense-table slots of the module (function starts + resume entries)
        size_t entryCount;
    };

    // Generated list of all packs (src/CMakeLists.txt -> kamite_generated/kamite/module_index.cpp).
    const ModulePack *const *modulePacks(size_t &count);
}
